"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "./ease";
export function ArtemisPriceNumber({ value }: { value: number }) {
  const reduce = useReducedMotion() === true;
  const text = String(value);
  return (
    <span className="art:relative art:inline-flex art:h-[1.24em] art:items-center art:overflow-hidden art:px-[0.06em] art:align-bottom">
      <span className="art:sr-only">{text}</span>
      <span aria-hidden className="art:invisible">
        {text}
      </span>
      <AnimatePresence initial={false}>
        <motion.span
          key={text}
          aria-hidden
          className="art:absolute art:inset-y-0 art:right-[0.06em] art:left-[0.06em] art:flex art:items-center art:leading-[1.1]"
          initial={reduce ? { opacity: 0 } : { opacity: 0, y: "55%", filter: "blur(6px)" }}
          animate={{ opacity: 1, y: "0%", filter: "blur(0px)" }}
          exit={reduce ? { opacity: 0 } : { opacity: 0, y: "-55%", filter: "blur(6px)" }}
          transition={{ duration: reduce ? 0 : 0.32, ease: ARTEMIS_EASE_OUT }}
