"use client";
// @zeus-internal
import { motion, useMotionValue, useReducedMotion, useSpring, useTransform } from "motion/react";
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent,
} from "react";
import { artemisCx } from "./utils";
export interface ArtemisRangeSliderProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  "aria-label"?: string;
  formatValueText?: (value: number) => string;
  showTicks?: boolean;
  className?: string;
}
export function artemisSnapRange(value: number, min: number, max: number, step: number) {
  if (max <= min) return min;
  const finite = Number.isFinite(value) ? value : min;
  if (finite >= max) return max;
  if (finite <= min) return min;
  const increment = Number.isFinite(step) && step > 0 ? step : 1;
  return Math.min(
    max,
    Math.max(min, Number((min + Math.round((finite - min) / increment) * increment).toFixed(10)))
  );
}
export function ArtemisRangeSlider({
  value,
  defaultValue = 0,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  disabled = false,
  "aria-label": label,
  formatValueText,
  showTicks = true,
  className,
}: ArtemisRangeSliderProps) {
  const root = useRef<HTMLDivElement>(null),
    thumb = useRef<HTMLDivElement>(null),
    placed = useRef(false),
    drag = useRef<{ id: number; previousSelect: string } | null>(null);
  const [internal, setInternal] = useState(defaultValue),
    [width, setWidth] = useState(0),
    [dragging, setDragging] = useState(false);
  const selected = artemisSnapRange(value ?? internal, min, max, step),
    reduced = useReducedMotion();
  const target = useMotionValue(0),
    glide = useSpring(target, { stiffness: 700, damping: 50, mass: 0.5 });
  const position = reduced ? target : glide;
  const fill = useTransform(position, (x) => x + 6 - Math.max(width - 4, 0));
  const last = useRef(selected);
  last.current = selected;
  useLayoutEffect(() => {
    if (!root.current) return;
    const node = root.current;
    const measure = () => setWidth(parseFloat(getComputedStyle(node).width) || node.clientWidth);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  useLayoutEffect(() => {
    const x = 8 + Math.max(0, width - 20) * (max > min ? (selected - min) / (max - min) : 0);
    if (width && !placed.current) {
      target.jump(x);
      glide.jump(x);
      placed.current = true;
    } else target.set(x);
  }, [selected, width, min, max, target]);
  const release = (event?: { pointerId: number }) => {
    const current = drag.current;
    if (!current || (event && current.id !== event.pointerId)) return;
    drag.current = null;
    document.body.style.userSelect = current.previousSelect;
    setDragging(false);
    if (root.current?.hasPointerCapture(current.id)) root.current.releasePointerCapture(current.id);
  };
  useEffect(() => {
    if (disabled) release();
  }, [disabled]);
  useEffect(
    () => () => {
      if (drag.current) document.body.style.userSelect = drag.current.previousSelect;
    },
    []
  );
  const commit = (next: number) => {
    const snapped = artemisSnapRange(next, min, max, step);
    if (snapped === last.current) return;
    last.current = snapped;
    if (value === undefined) setInternal(snapped);
    onValueChange?.(snapped);
  };
  const point = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    commit(
      min +
        Math.max(0, Math.min(1, (event.clientX - box.left) / Math.max(box.width, 1))) * (max - min)
    );
  };
  const down = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled || event.button !== 0 || !event.isPrimary) return;
    event.preventDefault();
    thumb.current?.focus();
    drag.current = { id: event.pointerId, previousSelect: document.body.style.userSelect };
    document.body.style.userSelect = "none";
    setDragging(true);
    event.currentTarget.setPointerCapture(event.pointerId);
    point(event);
  };
  const key = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    const increment = step > 0 ? step : 1;
    let next: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowUp":
        next = selected + increment;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        next = selected - increment;
        break;
      case "Home":
        next = min;
        break;
      case "End":
        next = max;
        break;
      case "PageUp":
        next = selected + increment * 10;
        break;
      case "PageDown":
        next = selected - increment * 10;
        break;
      default:
        return;
    }
    event.preventDefault();
    commit(next);
  };
  const tickCount = Math.floor((max - min) / Math.max(step, Number.EPSILON));
  return (
    <div
      ref={root}
      onPointerDown={down}
      onPointerMove={(event) => {
        if (drag.current?.id === event.pointerId) point(event);
      }}
      onPointerUp={release}
      onPointerCancel={release}
      onLostPointerCapture={release}
      className={artemisCx(
        "art:relative art:flex art:h-10 art:w-full art:touch-none art:items-center art:overflow-hidden art:rounded-lg art:bg-muted art:select-none art:[-webkit-touch-callout:none]",
        disabled
          ? "art:pointer-events-none art:opacity-50"
          : dragging
          ? "art:cursor-grabbing"
          : "art:cursor-grab",
        className
      )}
    >
      <div className="art:pointer-events-none art:absolute art:inset-x-0.5 art:inset-y-0 art:overflow-hidden art:rounded-lg">
        <motion.div
          className="art:h-full art:rounded-lg art:bg-foreground/15"
          style={{ width: Math.max(width - 4, 0), x: fill }}
        />
      </div>
      {showTicks && tickCount > 0 && tickCount <= 50 ? (
        <div
          aria-hidden="true"
          className="art:pointer-events-none art:absolute art:inset-x-2.5 art:inset-y-0"
        >
          {Array.from({ length: tickCount + 1 }, (_, index) => (
            <span
